from math import log2
from collections import Counter

def entropie(etiquettes):
    n = len(etiquettes)
    if n == 0:
        return 0.0
    h = 0.0
    for effectif in Counter(etiquettes).values():
        p = effectif / n
        if p > 0:
            h -= p * log2(p)
    return round(h, 4)

def gain(etiquettes, groupes):
    n = len(etiquettes)
    if n == 0:
        return 0.0
    reste = sum(len(g) / n * entropie(g) for g in groupes)
    return round(entropie(etiquettes) - reste, 4)

def matrice(y_vrai, y_pred):
    vp = fp = fn = vn = 0
    for a, b in zip(y_vrai, y_pred):
        if a == 1 and b == 1:
            vp += 1
        elif a == 0 and b == 1:
            fp += 1
        elif a == 1 and b == 0:
            fn += 1
        else:
            vn += 1
    return (vp, fp, fn, vn)

def scores(y_vrai, y_pred):
    vp, fp, fn, vn = matrice(y_vrai, y_pred)
    total = vp + fp + fn + vn
    exactitude = (vp + vn) / total if total else 0.0
    precision = vp / (vp + fp) if (vp + fp) else 0.0
    rappel = vp / (vp + fn) if (vp + fn) else 0.0
    f1 = 2 * precision * rappel / (precision + rappel) if (precision + rappel) else 0.0
    return {'exactitude': round(exactitude, 4), 'precision': round(precision, 4),
            'rappel': round(rappel, 4), 'f1': round(f1, 4)}

from sklearn.pipeline import make_pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.neighbors import KNeighborsClassifier
from sklearn.model_selection import cross_val_score, StratifiedKFold

def choisir_k(X, y, ks):
    decoupe = StratifiedKFold(n_splits=5, shuffle=True, random_state=0)
    meilleur_k, meilleur_score = None, -1.0
    for k in ks:
        modele = make_pipeline(StandardScaler(), KNeighborsClassifier(n_neighbors=k))
        score = round(float(cross_val_score(modele, X, y, cv=decoupe).mean()), 4)
        if score > meilleur_score:
            meilleur_k, meilleur_score = k, score
    return (meilleur_k, meilleur_score)
